import{_ as e,o as r,c as o,a5 as s}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"给表格添加其它实时响应数据，并保持性能最佳","description":"在虚拟化表格里再接入 “更多实时字段” 的关键思路 一句话 ： 把数据流和渲染彻底解耦 ，用 集中队列 + requestAnimationFrame 批量冲刷 + 虚拟滚动只订阅可视行 ，其余都走缓存或惰性计算。 1 . 数据来源层 —— 统一 WebSocket 消息流 做法。","frontmatter":{"title":"给表格添加其它实时响应数据，并保持性能最佳","date":"2026-08-11T00:00:00.000Z","categories":["React 系统教程"],"tags":["React","Redux","前端","教程","OneNote","性能与实战"],"description":"在虚拟化表格里再接入 “更多实时字段” 的关键思路 一句话 ： 把数据流和渲染彻底解耦 ，用 集中队列 + requestAnimationFrame 批量冲刷 + 虚拟滚动只订阅可视行 ，其余都走缓存或惰性计算。 1 . 数据来源层 —— 统一 WebSocket 消息流 做法。","sidebarWeight":23,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/应用/给表格添加其它实时响应数据，并保持性能最佳.md"},"headers":[],"relativePath":"posts/React系统教程/05-性能与实战/给表格添加其它实时响应数据，并保持性能最佳.md","filePath":"posts/React系统教程/05-性能与实战/给表格添加其它实时响应数据，并保持性能最佳.md"}'),n={name:"posts/React系统教程/05-性能与实战/给表格添加其它实时响应数据，并保持性能最佳.md"};function a(i,t,l,d,g,p){return r(),o("div",null,[...t[0]||(t[0]=[s('<div><h1 id="给表格添加其它实时响应数据-并保持性能最佳" tabindex="-1">给表格添加其它实时响应数据，并保持性能最佳 <a class="header-anchor" href="#给表格添加其它实时响应数据-并保持性能最佳" aria-label="Permalink to &quot;给表格添加其它实时响应数据，并保持性能最佳&quot;">​</a></h1><blockquote><p>本节目标：理解“给表格添加其它实时响应数据，并保持性能最佳”的核心思路，并能把它用于实际开发或面试表达。 <strong>在虚拟化表格里再接入 “更多实时字段” 的关键思路</strong><strong>一句话</strong>：<strong>把数据流和渲染彻底解耦</strong>，用 <strong>集中队列 + requestAnimationFrame 批量冲刷 + 虚拟滚动只订阅可视行</strong>，其余都走缓存或惰性计算。</p></blockquote><p><strong>1 . 数据来源层 —— 统一 WebSocket 消息流</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>做法</strong></td><td><strong>目的</strong></td></tr><tr><td><strong>所有实时字段（价差、成交量、仓位比、深度…）共用一条 WS 或 mux 多条 WS</strong></td><td>减少握手/心跳开销</td></tr><tr><td>解析后不要直接改行数据，<strong>先写入 Map&lt;symbol, Partial&lt;UpdatePayload&gt;&gt;</strong></td><td>把“变”收集起来，防抖</td></tr><tr><td><strong>不同字段分队列</strong> or 同队列但字段分片：priceQueue / volumeQueue …</td><td>方便不同刷新节奏</td></tr></tbody></table><p>interface UpdatePayload { bid?: number ask?: number spread?: number vol?: number // …按需扩展} <strong>2 . 批量刷新层 —— requestAnimationFrame 冲刷</strong> const queues = new Map&lt;string, UpdatePayload[]&gt;() function scheduleFlush() { if (rafId === null) rafId = requestAnimationFrame(flush)} function flush() { queues.forEach((list, sym) =&gt; { const snapshot = Object.assign({}, ...list) // 把一帧内同 symbol 的更新合并 list.length = 0 applyToRow(sym, snapshot) // 只对 Map/Ref 做一次写入 applyToOpenOrder(sym, snapshot) // 如需同步到其他表格 }) rafId = null} *️⃣ <strong>一个 raf 批一次</strong>，浏览器一次重排、一次重绘，表格行只更新真正变动的字段。</p><p><strong>3 . 状态存储层 —— Pinia Store “真源” + Weak 引用</strong></p><ul><li>const rowMap = computed(()=&gt; …) 已经很好；继续保持 <strong>Symbol → 行对象</strong>。</li><li>新增字段时在 applyToRow 里 <strong>按需动态添加</strong>，Vue 3 的 Proxy 能自动追踪。</li><li><strong>不要在行对象塞大对象</strong>，如深度列表等可存在 Map 里，只给行对象挂一个 hasDepth=true 标识。</li></ul><p><strong>4 . 视图层 —— 虚拟滚动 + 只订阅可视行</strong></p><ol><li><strong>onVisibleChange</strong> 拿到当前可视 symbols</li><li>tradeViewStore.subscribe([...visible], &#39;update&#39;)——已有</li><li><strong>丢给 feedStore / depthStore / whateverStore</strong> 拉其余字段</li><li>滚出视口的行 → unsubscribe（除非其它组件还在用）实践：一个 3,000 行列表，只订阅 30 – 50 行，轻松保持 &lt; 1 kB/s</li></ol><p><strong>5 . 性能兜底</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>场景</strong></td><td><strong>手段</strong></td></tr><tr><td><strong>爆量推送</strong>（几万条/秒）</td><td>WebSocket Server 端做 <strong>diff/聚合</strong>；前端可用 <strong>WebWorker</strong> 解析</td></tr><tr><td><strong>深度更新巨大</strong></td><td>单独的 &lt;DepthPanel&gt; 弹窗时才订阅；表格里只给“有深度”提示</td></tr><tr><td><strong>频繁 setState 还是卡</strong></td><td>markRaw or shallowRef 行对象，避免 Vue 深层递归 diff</td></tr></tbody></table><p><strong>简要流程图</strong> WebSocket → Queue&lt;Map&gt; → rAF flush ─┬─&gt; rowMap / reactive → 虚拟表格 └─&gt; 其它组件（指标面板…） <strong>核心总结</strong></p><ol><li><strong>集中队列</strong> 而非逐条 set → 降低更新频率</li><li><strong>rAF 对齐浏览器节奏</strong> → 减少重排</li><li><strong>虚拟滚动 + 可视订阅</strong> → 减少网络和内存</li><li><strong>Store 单一真源</strong> → 易维护、低耦合</li></ol><p>这样再加任何实时字段都只是 “多一个队列 + 一段合并逻辑”，性能稳住，代码也清晰。</p><p>这种做法是不是最佳实践，再给我重复一下完整的实现，一步步提供</p><p><strong>ChatGPT 说：</strong><strong>先回答“是不是最佳实践？”</strong></p><ul><li><strong>解耦</strong>　FeedStore 专管 <em>外部请求 + 本地缓存</em>，tradeViewStore 只管 <em>展示层数据</em>，这是 <strong>Store 单一职责</strong> 的典型做法；</li><li><strong>单一真源</strong>　所有 Feed 都统一落到 feedMap，行数据只是引用，避免同一份数据分散多处；</li><li><strong>响应式注入</strong>　用 watch 把 Feed 注回表格，没有手动 setState，符合 <strong>Vue 响应式</strong> 思路；</li><li><strong>按需拉取</strong>　只对“可见行”调用 fetchFeeds，避免大量无用请求。总体是当前 Pinia / Vue3 项目里较通行的写法。如果后期发现性能瓶颈，可再做 <strong>批量接口／LRU 缓存</strong> 等优化。</li></ul><p><strong>完整实现（一步步）</strong> 下面把所有改动拆成 4 步，你照顺序粘贴即可。</p><p><strong>步骤 1 — 类型与常量</strong> types/feed.ts</p><p>ts 复制编辑 // Feed 服务器返回的 article → 转成的业务对象export interface FeedInfo { header: { code: Array&lt;{ _type: string; __text: string }&gt; option: { watch: Array&lt;{ _type: string; __text: string }&gt; } term: string } story: { title: string // …有需要再补字段 } value?: string // bullish/bearish 数字，提前算好} /** 解析 XML 用到的临时接口（外部库 xml2js 的输出） <em>/export interface XmlJson { items?: { article: FeedAnalysis | FeedAnalysis[] }} export interface FeedAnalysis { analysis: { content: { header: FeedInfo[&#39;header&#39;] story: FeedInfo[&#39;story&#39;] } }} /</em>* term → watch._type 的映射 */export const TERM_OPINION_MAP: Record&lt;string, string&gt; = { short: &#39;OPINION_SHORT&#39;, medium: &#39;OPINION_MEDIUM&#39;, long: &#39;OPINION_LONG&#39;,} 在你已有 TableRow 上加两个字段（tradeViewStore.ts 里或公共类型文件）：</p><p>ts 复制编辑 export interface TableRow extends ForexSymbol { ... // 之前的 feed?: FeedInfo feedValue?: number}</p><p><strong>步骤 2 — FeedStore</strong> stores/useFeedStore.ts</p><p>ts 复制编辑 import { defineStore } from &#39;pinia&#39;import { ref } from &#39;vue&#39;import { http } from &#39;@/utils&#39;import xmlparser from &#39;fast-xml-parser&#39; // 你项目里已有import type { FeedInfo, XmlJson, FeedAnalysis } from &#39;@/types/feed&#39;import { TERM_OPINION_MAP } from &#39;@/types/feed&#39; export default defineStore(&#39;feed&#39;, () =&gt; { /** symbol → FeedInfo <em>/ const feedMap = ref&lt;Map&lt;string, FeedInfo&gt;&gt;(new Map()) /</em>* 外部调用，按 symbol 数组批量拉取 */ async function fetchFeeds(symbols: string[]) { if (!symbols.length) return const symbolStr = symbols.join(&#39;,&#39;) try { const resp = await http.get(&#39;/api/pub/get_feednews&#39;, { params: { type_product: &#39;null&#39;, product: symbolStr, term: &#39;null&#39;, culture: &#39;en&#39;, days: 1, last_ta: 1, }, transformResponse: (d: any) =&gt; d, }) const xmlStr = resp.data as string if (typeof xmlStr !== &#39;string&#39; || !xmlStr) return const xmlJson: XmlJson = xmlparser.parse(xmlStr) const rawArticles = xmlJson.items?.article if (!rawArticles) return const articles = Array.isArray(rawArticles) ? rawArticles : [rawArticles] articles.forEach((art: FeedAnalysis) =&gt; { const header = art.analysis?.content?.header const story = art.analysis?.content?.story if (!header || !story) return const ticker = header.code.find((c) =&gt; c._type === &#39;TICKER&#39;)?.__text if (!ticker) return const opinionKey = TERM_OPINION_MAP[header.term] const opinion = header.option.watch.find((w) =&gt; w._type === opinionKey)?.__text ?? &#39;&#39; const feed: FeedInfo = { header, story, value: opinion } feedMap.value.set(ticker, feed) }) } catch (e) { // 失败不抛给调用方，统一记录 console.error(&#39;fetchFeeds error&#39;, e) } } return { feedMap, fetchFeeds }})</p><p><strong>步骤 3 — tradeViewStore 集成</strong> stores/useTradeViewStore.ts <strong>增量改动</strong></p><p>ts 复制编辑 // 顶部 importimport useFeedStore from &#39;@/stores/useFeedStore&#39;...const feedStore = useFeedStore() <strong>3-a. 更新整表时注入 Feed</strong></p><p>ts 复制编辑 const updateFullSymbolList = (newList: TableRow[]) =&gt; { const m = feedStore.feedMap newList.forEach((row) =&gt; { const feed = m.get(row.symbol) if (feed) { row.feed = feed row.feedValue = +feed.value! || 0 } }) fullSymbolList.value = newList} <strong>3-b. 监听 FeedMap 实时回填</strong></p><p>ts 复制编辑 import { watch } from &#39;vue&#39;// …watch( () =&gt; feedStore.feedMap, (m) =&gt; { fullSymbolList.value.forEach((row) =&gt; { const f = m.get(row.symbol) if (f) { row.feed = f row.feedValue = +f.value! || 0 } }) }, { deep: true }) <strong>3-c. 可见行更新时顺带拉取 Feed</strong> 原来的 handler：</p><p>ts 复制编辑 function handleVisibleDataUpdated(symbols: string[]): void { tradeViewStore.subscribe(symbols, &#39;update&#39;)} 改成：</p><p>ts 复制编辑 function handleVisibleDataUpdated(symbols: string[]): void { tradeViewStore.subscribe(symbols, &#39;update&#39;) feedStore.fetchFeeds(symbols).catch(console.error)}</p><p><strong>步骤 4 — 组件渲染不变</strong> 因为 TableRow 已经多了 feed / feedValue，你原来的列 render 逻辑能直接工作，无需再改。</p><p><strong>✅</strong> <strong>至此功能完整</strong></p><ol><li><strong>SymbolList 滚动</strong> → 触发 visible-data-updated</li><li><strong>tradeViewStore.subscribe</strong> 保证价格 WebSocket；同一步骤调用 feedStore.fetchFeeds</li><li>拉回的 Feed 更新 feedMap → 被 watch 回写行对象</li><li>表格 cell 根据 record.feed 渲染箭头、tooltip</li><li>点击行弹窗可直接读取 record.feed.story 详细内容</li></ol><p>如果还有性能或复用需求，再考虑：</p><ul><li><strong>持久化 feedMap</strong>（Pinia Persist 或 IndexedDB）；</li><li><strong>接口去抖 / 批量缓存</strong>；</li><li><strong>把 feedValue 做成计算属性</strong> 而非冗余字段等。</li></ul><p>这样就把“TA/feed 分析”跟实时报价 &amp; 行情表格彻底解耦，同时保持响应式一致性，符合 Vue3 + Pinia 的最佳实践范式。</p></div>',1)])])}const u=e(n,[["render",a]]);export{f as __pageData,u as default};
